Let $\mathbf{X},\mathbf{Y}$ and $\mathbf{Z}$ be pairwise disjoint node sets in a causal DAG $\mathcal{G}$, such that $\mathbf{Z}$ is a valid adjustment set with respect to $(\mathbf{X},\mathbf{Y})$ and let $\mathbf{Z'}=\mathbf{X} \cup \mathbf{Z}$. Consider any pair of nodes $X\in \mathbf{X}, Y \in \mathbf{Y}$ and let $\mathbf{D}=\textup{cn}(X,Y,\mathcal{G}) \cap \textup{cn}(\mathbf{Z'},Y,\mathcal{G})$ be the set of all nodes $N \in \mathrm{cn}(X,Y,\mathcal{G})$, such that there exists a directed path from $N$ to $Y$ which contains no nodes from $\mathbf{Z'}$.
	Then the following two statements hold:
	\begin{enumerate}
		\item All non-causal paths from $X$ to $\mathbf{Y}$ are blocked by $\mathbf{Z'}_{-x}$. 
		\item $\mathrm{de}(\mathbf{D},\mathcal{G}) \cap \mathbf{Z'}_{-x} =\emptyset$. 
	\end{enumerate}

Let $X$ and $Y$ be two nodes in a causal DAG $\mathcal{G}=(\mathbf{V},\mathbf{E})$, let $\mathbf{V}$ follow a causal linear model compatible with $\mathcal{G}$ and let $\mathbf{Z'}$ be a node set, such that $X \in \mathbf{Z'}$ and $Y\notin \mathbf{Z'}$. If $\mathbf{Z'}_{-x}$ is a set that
	 \begin{enumerate}
	 	\item blocks all non-causal paths from $X$ to $Y$ in $\mathcal{G}$ and 
	 	\item fulfills that $\mathrm{de}(\mathbf{D},\mathcal{G}) \cap \mathbf{Z'}_{-x} =\emptyset$, where $\mathbf{D}=\text{cn}(X,Y,\mathcal{G}) \cap \text{cn}(\mathbf{Z'},Y,\mathcal{G})$,
	 \end{enumerate}
	 then $\delta_{y\mathbf{z'}} \protect\mathpalette{\protect\mathrel{\rlap{$}\perp$}\mkern2mu{}\perp}} \delta_{x\mathbf{z'}_{-x}}$.

Consider a causal DAG $\mathcal{G}=(\mathbf{V},\mathbf{E})$ and let $\mathbf{V}$ follow a causal linear model compatible with $\mathcal{G}$. Let $N$ be a node and $\mathbf{A}=\{A_1,\dots, A_k\}$ be a node set in $\mathcal{G}$, such that $N \notin \mathbf{A}$. Then 
	\begin{equation}
	\tau_{a_in} = \sum_{A_j \in \mathbf{A}} \tau_{a_jn.\mathbf{a}_{-j}} \tau_{a_ia_j}

	\end{equation}
	 for any $A_i \in \mathbf{A}$.

Let $\mathbf{V}=(\mathbf{S}^T,\mathbf{W}^T,\mathbf{Z}^T)^T$, with $\mathbf{S}$ possibly of length zero, be a mean $\mathbf{0}$ random vector with finite variance. Then 
\begin{align*}

\Sigma_{\mathbf{zz}.\mathbf{sw}} = \Sigma_{\mathbf{zz}.\mathbf{s}} - \boldsymbol{\beta}_{\mathbf{zw}.\mathbf{s}} \Sigma_{\mathbf{ww}.\mathbf{s}} \boldsymbol{\beta}^T_{\mathbf{zw}.\mathbf{s}}.
\end{align*}

Let $\mathbf{V} = (\mathbf{S}^T,\mathbf{T}^T,\mathbf{W}^T,\mathbf{Z}^T)^T$, with $\mathbf{Z}$ possibly of length zero, be a mean $\mathbf{0}$ random vector with finite variance.
Then


\begin{align}

\boldsymbol{\beta}_{\mathbf{tw}.\mathbf{z}} = 
\boldsymbol{\beta}_{\mathbf{tw}.\mathbf{sz}} 
+ \boldsymbol{\beta}_{\mathbf{ts}.\mathbf{wz}} \boldsymbol{\beta}_{\mathbf{sw}.\mathbf{z}}.  
\end{align}
